 q.append({'id':ident,'review_state':'proposed','question':prompt,'answer_reference':answer,'fact_cluster_proposed':cluster,'expected_concept':concept,'concept_family_seen_in_DEV':True,'independent_FINAL_eligible':False,'evidence':evidence})
